    margin: "0"
  },
  errorMessage: {
    backgroundColor: "#7f1d1d",
    color: "#fecaca",
    padding: "12px",
    borderRadius: "10px",
    marginTop: "15px",
    marginBottom: "15px",
    textAlign: "center",
    fontSize: "14px"
  },
  loginButton: {
    width: "100%",
    padding: "14px",
    fontSize: "16px",
    border: "none",
    borderRadius: "12px",
    cursor: "pointer",
    background: "linear-gradient(90deg, #0ea5e9, #2563eb)",
    color: "white",
    fontWeight: "bold",
    marginTop: "20px"
  },
  loginInfo: {
    marginTop: "25px",
    padding: "15px",
    backgroundColor: "#0f172a",
    border: "1px solid #334155",
    borderRadius: "10px"
  },
  loginInfoText: {
    color: "#94a3b8",
    fontSize: "13px",
    margin: "5px 0"
  },
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #0f172a, #111827, #1e293b)",
    color: "#f8fafc",
    fontFamily: "Arial, sans-serif",
    padding: "30px"
  },
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "30px",
    flexWrap: "wrap",
    gap: "15px"
  },
  logo: {
    fontSize: "24px",
    fontWeight: "bold",
    color: "#38bdf8"
  },
  navButtons: {
    display: "flex",
    gap: "10px",
    flexWrap: "wrap"
  },
  navButton: {
    backgroundColor: "#1e293b",
    color: "#f8fafc",
    border: "1px solid #334155",
    borderRadius: "8px",
    padding: "10px 16px",
    cursor: "pointer",
    fontSize: "14px",
    fontWeight: "500"
  },
  logoutButton: {
    backgroundColor: "#7f1d1d",
    color: "#fecaca",
    border: "1px solid #991b1b",
    borderRadius: "8px",
    padding: "10px 16px",
    cursor: "pointer"
  },
  heroSection: {
    textAlign: "center",
    padding: "40px 20px",
